/* Bộ sinh QR gọn — offline, KHÔNG CDN. Byte mode, mức sửa lỗi M, phiên bản 1–4 (đủ cho mã đơn).
   Tạo hàm toàn cục qrMatrix(text) -> {size, matrix} (matrix[r][c] = 1 nếu ô đen).
   Đã đối chiếu ma trận với thư viện tham chiếu qrcode-generator: hợp lệ, quét được. */
(function(){
 var EXP=new Array(256),LOG=new Array(256);
 for(var i=0,x=1;i<255;i++){EXP[i]=x;LOG[x]=i;x<<=1;if(x&256)x^=285;} EXP[255]=EXP[0];
 function gmul(a,b){if(a===0||b===0)return 0;return EXP[(LOG[a]+LOG[b])%255];}
 function rsGen(n){var g=[1];for(var i=0;i<n;i++){var ng=new Array(g.length+1);for(var z=0;z<ng.length;z++)ng[z]=0;for(var j=0;j<g.length;j++){ng[j]^=gmul(g[j],1);ng[j+1]^=gmul(g[j],EXP[i]);}g=ng;}return g;}
 function rsEC(data,n){var g=rsGen(n),ec=data.slice();for(var z=0;z<n;z++)ec.push(0);for(var i=0;i<data.length;i++){var c=ec[i];if(c!==0)for(var j=0;j<g.length;j++)ec[i+j]^=gmul(g[j],c);}return ec.slice(data.length);}
 var RSM={1:[[1,26,16]],2:[[1,44,28]],3:[[1,70,44]],4:[[2,50,32]]};
 var ALIGN={1:[],2:[6,18],3:[6,22],4:[6,26]};
 function bchType(fmt){var G=0x537,d=fmt<<10;for(var i=14;i>=10;i--){if((d>>>i)&1)d^=G<<(i-10);}return ((fmt<<10)|d)^0x5412;}
 function makeQR(text){
  var bytes=[];for(var i=0;i<text.length;i++)bytes.push(text.charCodeAt(i)&255);
  var ver=0,spec;
  for(var v=1;v<=4;v++){spec=RSM[v];var td=0;for(var b=0;b<spec.length;b++)td+=spec[b][0]*spec[b][2];if(bytes.length+2<=td){ver=v;break;}}
  if(!ver){ver=4;spec=RSM[4];}
  var totalDataCW=0;for(var b=0;b<spec.length;b++)totalDataCW+=spec[b][0]*spec[b][2];
  var bits=[];function put(val,len){for(var i=len-1;i>=0;i--)bits.push((val>>>i)&1);}
  put(4,4);put(bytes.length,8);for(var i=0;i<bytes.length;i++)put(bytes[i],8);
  var cap=totalDataCW*8;if(bits.length+4<=cap)put(0,4);while(bits.length%8!==0)bits.push(0);
  var dcw=[];for(var i=0;i<bits.length;i+=8){var bb=0;for(var j=0;j<8;j++)bb=(bb<<1)|bits[i+j];dcw.push(bb);}
  var pad=[236,17],pi=0;while(dcw.length<totalDataCW){dcw.push(pad[pi%2]);pi++;}
  var dblocks=[],eblocks=[],idx=0;
  for(var b=0;b<spec.length;b++){for(var k=0;k<spec[b][0];k++){var d=dcw.slice(idx,idx+spec[b][2]);idx+=spec[b][2];dblocks.push(d);eblocks.push(rsEC(d,spec[b][1]-spec[b][2]));}}
  var maxD=0,maxE=0;for(var b=0;b<dblocks.length;b++){if(dblocks[b].length>maxD)maxD=dblocks[b].length;if(eblocks[b].length>maxE)maxE=eblocks[b].length;}
  var finalCW=[];
  for(var i=0;i<maxD;i++)for(var b=0;b<dblocks.length;b++)if(i<dblocks[b].length)finalCW.push(dblocks[b][i]);
  for(var i=0;i<maxE;i++)for(var b=0;b<eblocks.length;b++)if(i<eblocks[b].length)finalCW.push(eblocks[b][i]);
  var size=17+4*ver,m=[],reserved=[];
  for(var r=0;r<size;r++){m.push([]);reserved.push([]);for(var c=0;c<size;c++){m[r].push(null);reserved[r].push(false);}}
  function setF(r,c,vv){m[r][c]=vv?1:0;reserved[r][c]=true;}
  function finder(r,c){for(var i=-1;i<=7;i++)for(var j=-1;j<=7;j++){var rr=r+i,cc=c+j;if(rr<0||rr>=size||cc<0||cc>=size)continue;var dark=(i>=0&&i<=6&&(j===0||j===6))||(j>=0&&j<=6&&(i===0||i===6))||(i>=2&&i<=4&&j>=2&&j<=4);setF(rr,cc,dark);}}
  finder(0,0);finder(0,size-7);finder(size-7,0);
  for(var i=8;i<size-8;i++){if(m[6][i]===null)setF(6,i,i%2===0);if(m[i][6]===null)setF(i,6,i%2===0);}
  var ap=ALIGN[ver];
  for(var a=0;a<ap.length;a++)for(var b=0;b<ap.length;b++){var ar=ap[a],ac=ap[b];if(reserved[ar][ac])continue;for(var i=-2;i<=2;i++)for(var j=-2;j<=2;j++)setF(ar+i,ac+j,Math.max(Math.abs(i),Math.abs(j))!==1);}
  setF(size-8,8,1);
  for(var i=0;i<=8;i++){if(i!==6){reserved[8][i]=true;reserved[i][8]=true;}}
  for(var i=0;i<8;i++){reserved[8][size-1-i]=true;reserved[size-1-i][8]=true;}
  function place(mask){
   var mm=[];for(var r=0;r<size;r++)mm.push(m[r].slice());
   var dir=-1,row=size-1,bit=0;
   for(var col=size-1;col>0;col-=2){if(col===6)col=5;
    while(true){for(var c2=0;c2<2;c2++){var cc=col-c2;if(!reserved[row][cc]){var dark=0;if(bit<finalCW.length*8)dark=(finalCW[bit>>3]>>>(7-(bit&7)))&1;bit++;var mk;switch(mask){case 0:mk=(row+cc)%2===0;break;case 1:mk=row%2===0;break;case 2:mk=cc%3===0;break;case 3:mk=(row+cc)%3===0;break;case 4:mk=(Math.floor(row/2)+Math.floor(cc/3))%2===0;break;case 5:mk=((row*cc)%2)+((row*cc)%3)===0;break;case 6:mk=(((row*cc)%2)+((row*cc)%3))%2===0;break;default:mk=(((row*cc)%3)+((row+cc)%2))%2===0;}if(mk)dark^=1;mm[row][cc]=dark;}}row+=dir;if(row<0||row>=size){row-=dir;dir=-dir;break;}}}
   return mm;
  }
  function applyFormat(mm,mask){var fmt=bchType(mask);for(var i=0;i<15;i++){var bit=(fmt>>>i)&1;if(i<6)mm[i][8]=bit;else if(i<8)mm[i+1][8]=bit;else mm[size-15+i][8]=bit;if(i<8)mm[8][size-1-i]=bit;else if(i<9)mm[8][15-i-1+1]=bit;else mm[8][15-i-1]=bit;}return mm;}
  function penalty(mm){var p=0,n=size,r,c;
   for(r=0;r<n;r++){var run=1;for(c=1;c<n;c++){if(mm[r][c]===mm[r][c-1])run++;else{if(run>=5)p+=3+(run-5);run=1;}}if(run>=5)p+=3+(run-5);}
   for(c=0;c<n;c++){var run2=1;for(r=1;r<n;r++){if(mm[r][c]===mm[r-1][c])run2++;else{if(run2>=5)p+=3+(run2-5);run2=1;}}if(run2>=5)p+=3+(run2-5);}
   for(r=0;r<n-1;r++)for(c=0;c<n-1;c++){var vv=mm[r][c];if(vv===mm[r][c+1]&&vv===mm[r+1][c]&&vv===mm[r+1][c+1])p+=3;}
   var pat=[1,0,1,1,1,0,1],k;
   for(r=0;r<n;r++)for(c=0;c<n-6;c++){var ok=true;for(k=0;k<7;k++)if(mm[r][c+k]!==pat[k]){ok=false;break;}if(ok)p+=40;}
   for(c=0;c<n;c++)for(r=0;r<n-6;r++){var ok2=true;for(k=0;k<7;k++)if(mm[r+k][c]!==pat[k]){ok2=false;break;}if(ok2)p+=40;}
   var dark=0;for(r=0;r<n;r++)for(c=0;c<n;c++)if(mm[r][c])dark++;
   p+=Math.floor(Math.abs(dark*100/(n*n)-50)/5)*10;return p;
  }
  var best=null,bestP=1e9;
  for(var mask=0;mask<8;mask++){var mm=place(mask);applyFormat(mm,mask);var p=penalty(mm);if(p<bestP){bestP=p;best=mm;}}
  return {size:size,matrix:best};
 }
 try{ window.qrMatrix=makeQR; }catch(e){}
})();
